#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.
#
# Run it on this machine with Git Bash (no WSL distro is installed):
#   "D:\tools\git\bin\bash.exe" "D:\Resources\DSH\_probe\wizard-install-gh-cli.sh"
# Smoke-test the plumbing without touching the machine:
#   GHC_DRY=1 "D:\tools\git\bin\bash.exe" "D:\Resources\DSH\_probe\wizard-install-gh-cli.sh"

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# ── runner helpers ────────────────────────────────────────────────────────
# Windows executables started from Git Bash each re-parse their own command
# line unless they are PowerShell, so PowerShell is only reached through a
# .ps1 heredoc here. That keeps every pathquote and UTF-8 path intact.
_PS_EXE="${PS_EXE:-powershell.exe}"

# _ps_stdin "ps1 body": run PowerShell 5.1 script text from stdin.
_ps_stdin() {
  local text="$1"
  [[ -n "${GHC_DRY:-}" ]] && { say "DRY RUN: skip PowerShell"; return 0; }
  printf '%s\n' "$text" | "$_PS_EXE" -NoProfile -NonInteractive -Command - 2>&1
}

# _gate "msg": a real wait for the human, skippable in smoke tests.
_gate() {
  if [[ -n "${GHC_NO_PAUSE:-}" ]]; then return 0; fi
  pause "${1:-Press Enter to continue}"
}

# gh_on_path: gh resolves through PATH *and* executes.
gh_on_path() {
  command -v gh >/dev/null 2>&1 && gh --version >/dev/null 2>&1
}

# _gh_dir_installed: true when gh.exe sits in one of the default install dirs,
# whether or not this shell's PATH already reaches it. A shell started before
# the installer edited PATH runs an older environment block, so PATH alone
# would report "not installed" for a working install.
_gh_dir_installed() {
  local d
  for d in "/c/Program Files/GitHub CLI" \
           "/c/Program Files (x86)/GitHub CLI" \
           "$HOME/AppData/Local/Programs/GitHub CLI" \
           "/c/ProgramData/chocolatey/bin"; do
    [[ -x "$d/gh.exe" ]] && return 0
  done
  local p
  for p in "$HOME"/AppData/Local/Programs/GitHub\ CLI/gh_*/bin; do
    [[ -x "$p/gh.exe" ]] && return 0
  done
  return 1
}

# _ensure_gh_path: make this shell see a gh installed into a default dir.
# Appends each candidate dir that actually holds gh.exe and is not already on
# PATH, so `command -v gh` afterwards reflects a real executable.
_ensure_gh_path() {
  local d extra=""
  for d in "/c/Program Files/GitHub CLI" \
           "/c/Program Files (x86)/GitHub CLI" \
           "$HOME/AppData/Local/Programs/GitHub CLI" \
           "/c/ProgramData/chocolatey/bin"; do
    [[ -x "$d/gh.exe" ]] || continue
    case ":$PATH:" in *":$d:"*) continue ;; esac
    extra="$extra:$d"
  done
  for d in "$HOME"/AppData/Local/Programs/GitHub\ CLI/gh_*/bin; do
    [[ -x "$d/gh.exe" ]] || continue
    case ":$PATH:" in *":$d:"*) continue ;; esac
    extra="$extra:$d"
  done
  if [[ -n "$extra" ]]; then
    PATH="$PATH${extra}"; export PATH
  fi
  return 0
}

# _glob1 PATTERN: the first matching directory name under the portable dir,
# or nothing when there is none (keeps PATH free of literal '*') .
_glob1() {
  local d
  for d in "$HOME"/AppData/Local/Programs/GitHub\ CLI/$1; do
    [[ -d "$d" ]] && { basename "$d"; return; }
  done
  return 0
}

# _record_version: write the machine-readable facts this wizard produced.
_record_version() {
  local v s
  v=$(gh --version 2>/dev/null | head -n1)
  v="${v#gh version }"
  v="${v%% *}"
  s=$(command -v gh)
  [[ -n "$v" ]] && write_env GH_CLI_VERSION "$v"
  [[ -n "$s" ]] && write_env GH_CLI_SOURCE "$s"
  GH_VERSION="$v"
}

# _record_user: capture the authenticated account, if any.
_record_user() {
  local u
  u=$(gh api user --jq .login 2>/dev/null || true)
  if [[ -n "$u" ]]; then
    write_env GH_CLI_USER "$u"
    GH_USER="$u"
  fi
}

# _user_path_add_gh: append the GitHub CLI dir to the *user* PATH (HKCU). No
# admin, no restart for new shells; DSH itself picks it up when it restarts.
_user_path_add_gh() {
  _ps_stdin '
$ErrorActionPreference = "Stop"
$targets = @(
  (Join-Path $env:ProgramFiles "GitHub CLI"),
  (Join-Path ${env:ProgramFiles(x86)} "GitHub CLI"),
  (Join-Path $env:LOCALAPPDATA "Programs\GitHub CLI")
) | Where-Object { $_ -and (Test-Path -LiteralPath (Join-Path $_ "gh.exe")) }
if (-not $targets) { Write-Output "no gh.exe found in the usual install directories"; exit 0 }
$cur = [Environment]::GetEnvironmentVariable("Path", "User")
$parts = @($cur -split ";" | Where-Object { $_ -ne "" })
foreach ($t in $targets) { if ($parts -notcontains $t) { $parts += $t } }
$new = $parts -join ";"
if ($new -eq $cur) { Write-Output "user PATH already contained the GitHub CLI directory"; exit 0 }
$key = Get-Item "HKCU:\Environment"
if ($key.GetValueKind("Path") -eq "ExpandString") {
  Set-ItemProperty "HKCU:\Environment" -Name Path -Value $new -Type ExpandString
} else {
  Set-ItemProperty "HKCU:\Environment" -Name Path -Value $new
}
Write-Output ("added to user PATH: " + ($targets -join ", "))
'
}

# _portable_install: download the official zip and unpack it under
# %LOCALAPPDATA%\Programs\GitHub CLI. Used when winget and the MSI are out.
_portable_install() {
  local dest tmpw zipw out
  dest="$HOME/AppData/Local/Programs/GitHub CLI"
  mkdir -p "$dest" "$HOME/AppData/Local/Temp/gh-wizard"
  zipw=$(cygpath -w "$dest")
  tmpw=$(cygpath -w "$HOME/AppData/Local/Temp/gh-wizard")
  out=$(_ps_stdin "\$ErrorActionPreference='Stop'
\$a = (Invoke-RestMethod -UseBasicParsing 'https://api.github.com/repos/cli/cli/releases/latest').assets
\$asset = \$a | Where-Object { \$_.name -like '*windows_amd64.zip' } | Select-Object -First 1
if (-not \$asset) { Write-Output 'no windows_amd64.zip asset found'; exit 1 }
\$z = Join-Path '$tmpw' 'gh.zip'
Invoke-WebRequest -UseBasicParsing \$asset.browser_download_url -OutFile \$z
Expand-Archive -Path \$z -DestinationPath '$zipw' -Force
Get-ChildItem '$zipw' | Select-Object -ExpandProperty Name")
  printf '%s\n' "$out"
  [[ "$out" == *"gh_"* ]]
}

run_wizard() {

TOTAL_STAGES=5

banner "Install GitHub CLI (gh) — Windows"

# ── Stage 1 ────────────────────────────────────────────────────────────────
stage "Check what is already here"
say "gh ships for Windows as one executable; winget and the official MSI both install it."
note "This wizard records what it learns in $ENV_FILE (created mode 0600)."
say ""

GH_BEFORE=""
GH_SOURCE=""
_ensure_gh_path
if gh_on_path; then
  GH_BEFORE=$(gh --version 2>/dev/null | head -n1)
  GH_SOURCE=$(command -v gh)
  printf '  %s✓ gh already installed%s — %s (%s)\n' "$GREEN" "$RESET" "$GH_BEFORE" "$GH_SOURCE"
elif _gh_dir_installed; then
  warn "gh.exe is installed, but this shell's PATH predates the installer — run a new terminal (or restart DSH) to pick it up"
else
  warn "gh is not on PATH yet — stages 2-3 install it"
fi
say ""
if command -v winget.exe >/dev/null 2>&1; then
  say "winget: $(winget.exe --version 2>/dev/null | head -n1)"
else
  warn "winget.exe not reachable from this shell — you will use the MSI path in stage 3"
fi
say ""
say "Official site: https://cli.github.com/"
_gate

# ── Stage 2 ────────────────────────────────────────────────────────────────
stage "Install: winget (the official GitHub.cli package)"
say "Listed on cli.github.com; a UAC prompt appears, so approve it on the desktop."
say ""
if ! command -v winget.exe >/dev/null 2>&1; then
  warn "winget.exe is not reachable here; skip to stage 3 (MSI)."
elif gh_on_path; then
  say "gh is already runnable, so nothing needs installing."
  if confirm "Upgrade to the newest release anyway?"; then
    if [[ -n "${GHC_DRY:-}" ]]; then
      say "DRY RUN: would execute  winget upgrade --id GitHub.cli --exact"
    else
      winget.exe upgrade --id GitHub.cli --exact --accept-source-agreements --accept-package-agreements || \
        warn "winget returned $? — read its output before continuing"
    fi
  fi
else
  if [[ -n "${GHC_DRY:-}" ]]; then
    say "DRY RUN: would execute  winget install --id GitHub.cli --exact"
  else
    say "Running: winget install --id GitHub.cli --exact"
    if winget.exe install --id GitHub.cli --exact --accept-source-agreements --accept-package-agreements; then
      printf '  %s✓ winget finished%s\n' "$GREEN" "$RESET"
    else
      warn "winget did not finish cleanly; stage 3 (MSI) is the fallback"
    fi
  fi
fi
_gate

# ── Stage 3 ────────────────────────────────────────────────────────────────
stage "Verify, then fix PATH if the shell still can't see gh"
_ensure_gh_path
if gh_on_path; then
  printf '  %s✓ gh runs here%s — %s\n' "$GREEN" "$RESET" "$(gh --version | head -n1)"
  GH_READY=1
else
  GH_READY=0
  warn "this shell still cannot run gh"
  say ""
  say "Fallback B — the official MSI (works without winget):"
  open_url "https://github.com/cli/cli/releases/latest"
  step "Under 'Assets → Windows', download gh_<version>_windows_amd64.msi (arm64 on ARM PCs)."
  step "Double-click it, approve UAC, click Finish."
  say ""
  say "Fallback C — the portable zip, no installer at all:"
  if confirm "Download and unzip the portable build into %LOCALAPPDATA%\\Programs\\GitHub CLI?"; then
    if _portable_install; then
      printf '  %s✓ portable build%s installed under %s\n' "$GREEN" "$RESET" "$HOME/AppData/Local/Programs/GitHub CLI"
    else
      warn "the portable install failed; the MSI above is the reliable path"
    fi
  fi
  _ensure_gh_path
  if gh_on_path; then
    GH_READY=1
    _record_version
  fi
  say ""
  say "Installer PATH changes only reach shells started afterwards, and the DSH"
  say "app keeps the PATH it started with. Extending the user PATH now is safe:"
  if confirm "Add the GitHub CLI directory to your user PATH?"; then
    if _user_path_add_gh; then
      printf '  %s✓ user PATH handled%s — new terminals and the next DSH start see gh\n' "$GREEN" "$RESET"
    else
      SKIPPED+=("user PATH still misses the GitHub CLI directory")
    fi
  fi
fi
_gate

# ── Stage 4 ────────────────────────────────────────────────────────────────
stage "Authenticate with your GitHub account"
if ! gh_on_path; then
  warn "gh is not runnable here, so login waits; re-run this wizard afterwards."
  SKIPPED+=("gh auth login (gh not runnable in this shell)")
else
  _record_version
  if gh auth status >/dev/null 2>&1; then
    _record_user
    printf '  %s✓ already logged in%s as %s\n' "$GREEN" "$RESET" "${GH_USER:-?}"
  else
    say "gh auth login is interactive, so run it on the console:"
    step "Open Windows Terminal or PowerShell (no administrator needed)."
    step "Run:  gh auth login"
    step "Pick: GitHub.com → HTTPS → 'Login with a web browser'."
    step "Copy the one-time code, press Enter, paste it, approve in the browser."
    note "That code is short-lived; it stays in your terminal, this wizard never sees it."
    note "Re-run the wizard afterwards and stage 4 records the account."
  fi
fi
_gate

# ── Stage 5 ────────────────────────────────────────────────────────────────
stage "Verify"
_ensure_gh_path
if gh_on_path; then
  printf '  %s✓ gh --version%s → %s\n' "$GREEN" "$RESET" "$(gh --version | head -n1)"
  _record_version
  if gh auth status >/dev/null 2>&1; then
    _record_user
    printf '  %s✓ authenticated%s as %s\n' "$GREEN" "$RESET" "${GH_USER:-?}"
  else
    warn "installed but not logged in — run 'gh auth login' when you want to"
    SKIPPED+=("gh auth login (not done yet)")
  fi
else
  warn "gh still does not run in this shell"
  SKIPPED+=("verify (gh not runnable: restart the terminal, then re-run)")
fi
say ""
say "Restarting DSH later picks up the new PATH, so agent shells get gh too."
note "Docs: https://cli.github.com/ · manual: https://cli.github.com/manual/"
_gate

finish
}

run_wizard "$@"; exit
